<?php
/**
 * Minimal Composer-free PSR-4 autoloader for the vendored PDF stack.
 *
 * This project intentionally has no Composer/Node build step (see README —
 * "ZIP kecil & deployment XAMPP sederhana"), so instead of running
 * `composer install`, the required libraries are vendored as plain source
 * trees under /vendor and wired up here.
 *
 * Covers:
 *   - dompdf/dompdf            (Dompdf\...)            -> vendor/dompdf/dompdf/src, /lib
 *   - phenx/php-font-lib       (FontLib\...)           -> vendor/phenx/php-font-lib/src
 *   - phenx/php-svg-lib        (Svg\...)               -> vendor/phenx/php-svg-lib/src
 *   - sabberworm/php-css-parser(Sabberworm\CSS\...)    -> vendor/sabberworm/php-css-parser/src
 *   - masterminds/html5        (Masterminds\HTML5\...) -> vendor/masterminds/html5/src
 *
 * If you ever switch to Composer, just `composer require dompdf/dompdf`
 * and delete this file + the /vendor folders above (require
 * vendor/autoload.php generated by Composer instead).
 */
declare(strict_types=1);

spl_autoload_register(function (string $class): void {
    // Map of namespace prefix -> one or more base directories (PSR-4 style).
    static $map = [
        'Dompdf\\'      => [__DIR__ . '/dompdf/dompdf/src', __DIR__ . '/dompdf/dompdf/lib'],
        'FontLib\\'     => [__DIR__ . '/phenx/php-font-lib/src/FontLib'],
        'Svg\\'         => [__DIR__ . '/phenx/php-svg-lib/src/Svg'],
        'Sabberworm\\CSS\\' => [__DIR__ . '/sabberworm/php-css-parser/src'],
        // masterminds/html5's PSR-4 root is the "Masterminds" namespace itself
        // (HTML5.php declares `namespace Masterminds;`), not "Masterminds\HTML5".
        'Masterminds\\' => [__DIR__ . '/masterminds/html5/src'],
    ];

    foreach ($map as $prefix => $dirs) {
        if (strncmp($class, $prefix, strlen($prefix)) !== 0) {
            continue;
        }
        $relative = substr($class, strlen($prefix));
        $relativePath = str_replace('\\', '/', $relative) . '.php';
        foreach ($dirs as $dir) {
            $file = $dir . '/' . $relativePath;
            if (is_file($file)) {
                require $file;
                return;
            }
        }
    }
});
